<?php
session_start();require __DIR__.'/../config/database.php';require __DIR__.'/../includes/helpers.php';require_login();$uid=(int)$_SESSION['user']['id'];$id=(int)($_GET['id']??0);
$st=$pdo->prepare("SELECT t.*,u.full_name owner_name FROM trips t JOIN users u ON u.id=t.owner_id WHERE t.id=? AND (t.status='published' OR t.owner_id=? OR EXISTS(SELECT 1 FROM trip_members x WHERE x.trip_id=t.id AND x.user_id=?))");$st->execute([$id,$uid,$uid]);$trip=$st->fetch();if(!$trip){http_response_code(404);exit('Trip not found');}
$st=$pdo->prepare('SELECT i.*,l.name location_name,l.image_url FROM itineraries i LEFT JOIN locations l ON l.id=i.location_id WHERE i.trip_id=? ORDER BY i.day_number,i.start_time');$st->execute([$id]);$items=$st->fetchAll();
$st=$pdo->prepare('SELECT e.*,u.full_name FROM expenses e JOIN users u ON u.id=e.paid_by WHERE e.trip_id=? ORDER BY e.expense_date DESC,e.id DESC');$st->execute([$id]);$expenses=$st->fetchAll();$totalExpense=(float)array_sum(array_map(fn($x)=>(float)$x['amount'],$expenses));
$st=$pdo->prepare('SELECT tm.*,u.full_name,u.email FROM trip_members tm JOIN users u ON u.id=tm.user_id WHERE tm.trip_id=? ORDER BY tm.member_role DESC,u.full_name');$st->execute([$id]);$members=$st->fetchAll();$isOwner=((int)$trip['owner_id']===$uid);$isMember=false;foreach($members as $mm){if((int)$mm['user_id']===$uid){$isMember=true;break;}}
$pdo->exec("CREATE TABLE IF NOT EXISTS checklist_progress (id INT UNSIGNED AUTO_INCREMENT PRIMARY KEY, checklist_id INT UNSIGNED NOT NULL, user_id INT UNSIGNED NOT NULL, is_completed TINYINT(1) NOT NULL DEFAULT 0, updated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP, UNIQUE KEY uq_checklist_user(checklist_id,user_id), FOREIGN KEY (checklist_id) REFERENCES checklists(id) ON UPDATE CASCADE ON DELETE CASCADE, FOREIGN KEY (user_id) REFERENCES users(id) ON UPDATE CASCADE ON DELETE CASCADE, INDEX idx_progress_user(user_id,checklist_id)) ENGINE=InnoDB");$pdo->prepare('INSERT IGNORE INTO checklist_progress(checklist_id,user_id) SELECT c.id,? FROM checklists c WHERE c.trip_id=?')->execute([$uid,$id]);$st=$pdo->prepare('SELECT c.*,COALESCE(cp.is_completed,0) AS user_completed FROM checklists c LEFT JOIN checklist_progress cp ON cp.checklist_id=c.id AND cp.user_id=? WHERE c.trip_id=? ORDER BY c.item_order,c.id');$st->execute([$uid,$id]);$checklists=$st->fetchAll();$readinessStmt=$pdo->prepare('SELECT tm.user_id,u.full_name,tm.member_role,COUNT(c.id) AS total_items,COALESCE(SUM(CASE WHEN cp.is_completed=1 THEN 1 ELSE 0 END),0) AS completed_items FROM trip_members tm JOIN users u ON u.id=tm.user_id LEFT JOIN checklists c ON c.trip_id=tm.trip_id LEFT JOIN checklist_progress cp ON cp.checklist_id=c.id AND cp.user_id=tm.user_id WHERE tm.trip_id=? GROUP BY tm.user_id,u.full_name,tm.member_role ORDER BY tm.member_role DESC,u.full_name');$readinessStmt->execute([$id]);$memberReadiness=$readinessStmt->fetchAll();$allReady=!empty($memberReadiness)&&count(array_filter($memberReadiness,fn($m)=>(int)$m['total_items']>0 && (int)$m['completed_items']<(int)$m['total_items']))===0;
$st=$pdo->prepare('SELECT l.* FROM locations l WHERE l.destination_id=? ORDER BY l.rating DESC,l.id DESC LIMIT 30');$st->execute([(int)$trip['destination_id']]);$locations=$st->fetchAll();
$percent=$trip['budget']>0?min(100,round(($totalExpense/$trip['budget'])*100)):0;
if($_SERVER['REQUEST_METHOD']==='POST'){verify_csrf();$action=$_POST['action']??'';
 if($action==='delete_trip' && (int)$trip['owner_id']===$uid){$pdo->prepare('DELETE FROM trips WHERE id=? AND owner_id=?')->execute([$id,$uid]);flash('success','Đã xóa chuyến đi.');redirect('user/trips.php');}
 if($action==='remove_member'){if(!$isOwner){http_response_code(403);exit('Forbidden: bạn không có quyền chỉnh sửa.');}$memberId=(int)$_POST['member_id'];if($memberId===$uid){flash('danger','Không thể xóa chủ chuyến đi.');}else{$pdo->prepare("DELETE FROM trip_members WHERE trip_id=? AND user_id<>? AND user_id=?")->execute([$id,$uid,$memberId]);flash('info','Đã xóa thành viên.');}redirect('user/trip-detail.php?id='.$id.'#members');}
 if($action==='toggle_publish'){$newStatus=($trip['status']==='published'?'draft':'published');$pdo->prepare('UPDATE trips SET status=? WHERE id=? AND owner_id=?')->execute([$newStatus,$id,$uid]);flash('success',$newStatus==='published'?'Đã publish chuyến đi.':'Đã chuyển về bản nháp.');redirect('user/trip-detail.php?id='.$id);}
  if($action==='add_itinerary'){if(!$isOwner){http_response_code(403);exit('Forbidden: chỉ chủ chuyến đi mới được chỉnh sửa lịch trình.');}$locationId=(int)($_POST['location_id']??0);$dayNumber=max(1,(int)($_POST['day_number']??1));$startTime=$_POST['start_time']??'';$endTime=$_POST['end_time']??null;$note=trim($_POST['note']??'');$check=$pdo->prepare('SELECT id FROM locations WHERE id=? AND destination_id=?');$check->execute([$locationId,(int)$trip['destination_id']]);if(!$check->fetchColumn()){flash('danger','Địa điểm này không thuộc điểm đến của chuyến đi.');redirect('user/trip-detail.php?id='.$id.'#itinerary');}$pdo->prepare('INSERT INTO itineraries(trip_id,location_id,day_number,start_time,end_time,note) VALUES(?,?,?,?,?,?)')->execute([$id,$locationId,$dayNumber,$startTime,$endTime?:null,$note]);flash('success','Đã thêm lịch trình.');redirect('user/trip-detail.php?id='.$id.'#itinerary');}
  if($action==='delete_itinerary'){if(!$isOwner){http_response_code(403);exit('Forbidden: chỉ chủ chuyến đi mới được chỉnh sửa lịch trình.');}$pdo->prepare('DELETE FROM itineraries WHERE id=? AND trip_id=?')->execute([(int)$_POST['item_id'],$id]);flash('info','Đã xóa lịch trình.');redirect('user/trip-detail.php?id='.$id.'#itinerary');}
  if($action==='add_expense'){if(!$isOwner){http_response_code(403);exit('Forbidden: chỉ chủ chuyến đi mới được chỉnh sửa ngân sách.');}$amount=(float)($_POST['amount']??0);$expenseDate=$_POST['expense_date']??'';$startDate=$trip['start_date'];$endDate=$trip['end_date'];if($amount<=0){flash('danger','Số tiền phải lớn hơn 0.');redirect('user/trip-detail.php?id='.$id.'#budget');}if($expenseDate<$startDate||$expenseDate>$endDate){flash('danger','Ngày chi phải nằm trong khoảng từ '.date('d/m/Y',strtotime($startDate)).' đến '.date('d/m/Y',strtotime($endDate)).'.');redirect('user/trip-detail.php?id='.$id.'#budget');}$sum=$pdo->prepare('SELECT COALESCE(SUM(amount),0) FROM expenses WHERE trip_id=?');$sum->execute([$id]);$currentTotal=(float)$sum->fetchColumn();if($currentTotal+$amount>(float)$trip['budget']){flash('danger','Không thể thêm khoản chi: tổng chi sẽ vượt ngân sách '.number_format($trip['budget'],0,',','.').'đ.');redirect('user/trip-detail.php?id='.$id.'#budget');}$pdo->prepare('INSERT INTO expenses(trip_id,paid_by,category,amount,description,expense_date) VALUES(?,?,?,?,?,?)')->execute([$id,$uid,trim($_POST['category']),$amount,trim($_POST['description']),$expenseDate]);flash('success','Đã thêm chi phí.');redirect('user/trip-detail.php?id='.$id.'#budget');}
  if($action==='delete_expense'){if(!$isOwner){http_response_code(403);exit('Forbidden: chỉ chủ chuyến đi mới được chỉnh sửa ngân sách.');}$pdo->prepare('DELETE FROM expenses WHERE id=? AND trip_id=? AND paid_by=?')->execute([(int)$_POST['expense_id'],$id,$uid]);flash('info','Đã xóa khoản chi.');redirect('user/trip-detail.php?id='.$id.'#budget');}
 if($action==='add_member'){if(!$isOwner){http_response_code(403);exit('Forbidden: chỉ chủ chuyến đi mới được thêm thành viên.');}$email=trim($_POST['email']??'');$st=$pdo->prepare('SELECT id,full_name FROM users WHERE email=? AND status=\'active\'');$st->execute([$email]);$m=$st->fetch();if(!$m){flash('danger','Không tìm thấy tài khoản hợp lệ.');}elseif((int)$m['id']===$uid){flash('danger','Bạn đã là chủ chuyến đi, không cần thêm chính mình.');}else{$check=$pdo->prepare('SELECT 1 FROM trip_members WHERE trip_id=? AND user_id=?');$check->execute([$id,$m['id']]);if($check->fetchColumn()){flash('info','Tài khoản này đã là thành viên của chuyến đi.');}else{$pdo->prepare('INSERT INTO trip_members(trip_id,user_id,member_role) VALUES(?,?,\'member\')')->execute([$id,$m['id']]);$pdo->prepare('INSERT IGNORE INTO checklist_progress(checklist_id,user_id) SELECT id,? FROM checklists WHERE trip_id=?')->execute([(int)$m['id'],$id]);flash('success','Đã thêm thành viên.');}}redirect('user/trip-detail.php?id='.$id.'#members');}
  if($action==='add_checklist'){if(!$isOwner){http_response_code(403);exit('Forbidden: chỉ chủ chuyến đi mới được chỉnh sửa checklist.');}$name=trim($_POST['item_name']??'');if($name){$q=$pdo->prepare('SELECT COALESCE(MAX(item_order)+1,0) FROM checklists WHERE trip_id=?');$q->execute([$id]);$order=(int)$q->fetchColumn();$pdo->prepare('INSERT INTO checklists(trip_id,item_name,is_completed,item_order) VALUES(?,?,0,?)')->execute([$id,$name,$order]);$checklistId=(int)$pdo->lastInsertId();$pdo->prepare('INSERT IGNORE INTO checklist_progress(checklist_id,user_id) SELECT ?,user_id FROM trip_members WHERE trip_id=?')->execute([$checklistId,$id]);flash('success','Đã thêm checklist.');}redirect('user/trip-detail.php?id='.$id.'#checklist');}
  if($action==='toggle_checklist'){if(!$isMember){http_response_code(403);exit('Forbidden: bạn không phải thành viên của chuyến đi.');}$checklistId=(int)($_POST['item_id']??0);$q=$pdo->prepare('SELECT id FROM checklists WHERE id=? AND trip_id=?');$q->execute([$checklistId,$id]);if(!$q->fetchColumn()){http_response_code(404);exit('Checklist not found');}$pdo->prepare('INSERT INTO checklist_progress(checklist_id,user_id,is_completed) VALUES(?,?,1) ON DUPLICATE KEY UPDATE is_completed=1-is_completed')->execute([$checklistId,$uid]);redirect('user/trip-detail.php?id='.$id.'#checklist');}
  if($action==='delete_checklist'){if(!$isOwner){http_response_code(403);exit('Forbidden: chỉ chủ chuyến đi mới được chỉnh sửa checklist.');}$pdo->prepare('DELETE FROM checklists WHERE id=? AND trip_id=?')->execute([(int)$_POST['item_id'],$id]);flash('info','Đã xóa mục checklist.');redirect('user/trip-detail.php?id='.$id.'#checklist');}
}
