<section id="checklist" class="panel mt-4"><div class="d-flex justify-content-between align-items-center"><div><div class="eyebrow">PREPARE</div><h2 class="fw-800 fs-4 mb-0">Checklist trước chuyến đi</h2><div class="small text-secondary mt-1">Mỗi thành viên tự đánh dấu những việc mình đã chuẩn bị.</div></div><span class="pill"><?= count(array_filter($checklists, fn($c)=>(int)$c['user_completed']===1)) ?>/<?= count($checklists) ?> đã xong</span></div><?php if($isOwner): ?><form method="post" class="input-group mt-3"><input type="hidden" name="csrf" value="<?= e(csrf_token()) ?>"><input type="hidden" name="action" value="add_checklist"><input class="form-control" name="item_name" placeholder="Ví dụ: Mang CCCD, sạc dự phòng..." required><button class="btn btn-primary">Thêm</button></form><?php else: ?><div class="alert alert-light border small mt-3 mb-0">Danh sách do chủ chuyến đi tạo. Mỗi thành viên tự đánh dấu phần mình đã chuẩn bị.</div><?php endif; ?><div class="mt-3"><?php if(!$checklists): ?><div class="empty-state">Chưa có việc cần chuẩn bị.</div><?php else: ?><?php foreach($checklists as $c): ?><div class="member-row"><form method="post" class="me-2"><input type="hidden" name="csrf" value="<?= e(csrf_token()) ?>"><input type="hidden" name="action" value="toggle_checklist"><input type="hidden" name="item_id" value="<?= $c['id'] ?>"><button class="btn btn-sm <?= $c['user_completed']?'btn-success':'btn-outline-secondary' ?>" type="submit"><?= $c['user_completed']?'✓':'○' ?></button></form><div class="flex-grow-1 <?= $c['user_completed']?'text-decoration-line-through text-secondary':'' ?>"><?= e($c['item_name']) ?></div><?php if($isOwner): ?><form method="post"><input type="hidden" name="csrf" value="<?= e(csrf_token()) ?>"><input type="hidden" name="action" value="delete_checklist"><input type="hidden" name="item_id" value="<?= $c['id'] ?>"><button class="btn btn-sm btn-link text-danger p-0">Xóa</button></form><?php endif; ?></div><?php endforeach; ?><?php endif; 