ck" style="font-size:12px"><?= e($l['name']) ?></strong><small class="text-secondary">⭐ <?= e($l['rating']) ?> · <?= number_format($l['average_cost'],0,',','.') ?>đ</small></div><?php if($isOwner): ?><button class="btn btn-sm btn-light border" data-bs-toggle="modal" data-bs-target="#itinModal">＋</button><?php endif; ?></div><?php endforeach; ?></section></div>
