<?php if($isOwner): ?>
<script>
document.addEventListener('DOMContentLoaded', function () {
  const expenseForm = document.querySelector('#expenseModal form');
  if (!expenseForm) return;
  const amountInput = expenseForm.querySelector('[name="amount"]');
  const budget = <?= json_encode((float)$trip['budget']) ?>;
  const spent = <?= json_encode((float)$totalExpense) ?>;
  const remaining = Math.max(0, budget - spent);
  const money = n => new Intl.NumberFormat('vi-VN').format(n) + 'đ';
  const oldAlert = document.getElementById('expenseBudgetAlert');
  if (!oldAlert) {
    const box = document.createElement('div');
    box.id = 'expenseBudgetAlert';
    box.className = 'alert alert-danger d-none mt-3 mb-0';
    amountInput.closest('.mb-3').after(box);
  }
  const alertBox = document.getElementById('expenseBudgetAlert');
  function validateBudget(showMessage) {
    const amount = Number(amountInput.value || 0);
    if (amount > remaining) {
      alertBox.textContent = 'Không thể thêm khoản chi. Bạn chỉ còn ' + money(remaining) + ', nhưng đang nhập ' + money(amount) + '.';
      alertBox.classList.remove('d-none');
      return false;
    }
    alertBox.classList.add('d-none');
    return true;
  }
  amountInput.addEventListener('input', () => validateBudget(false));
  expenseForm.addEventListener('submit', function (e) {
    if (!validateBudget(true)) {
      e.preventDefault();
      amountInput.focus();
    }
  });
});
</script>
<?php endif; ?>
